// SEO helpers for the public site: per-page metadata, JSON-LD and sitemap
// entries. Pure functions (relative imports) so they are unit-testable.

import type { Metadata, MetadataRoute } from "next";

import { site, socialLinks, type SiteConfig } from "../../content/site";
import type { PortfolioListResult } from "./api";

export const DEFAULT_OG_IMAGE = {
  // Generated by src/app/opengraph-image.tsx (root segment → stable path).
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "Velan Spaces — interior design and construction",
};

export const DEFAULT_TITLE = site.city
  ? `${site.name} — Interior design & construction in ${site.city}`
  : `${site.name} — Interior design & construction`;

type PageMetadataInput = {
  /** Page title without the brand suffix. Omit on the home page. */
  title?: string;
  description: string;
  /** Path beginning with "/", used for the canonical URL and og:url. */
  path: string;
  image?: { url: string; width?: number; height?: number; alt?: string };
  noIndex?: boolean;
};

export function pageMetadata({ title, description, path, image, noIndex }: PageMetadataInput): Metadata {
  const fullTitle = title ? `${title} · ${site.name}` : DEFAULT_TITLE;
  const ogImage = image ?? DEFAULT_OG_IMAGE;
  return {
    title: title ?? { absolute: DEFAULT_TITLE },
    description,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "en_IN",
      siteName: site.name,
      url: path,
      title: fullTitle,
      description,
      images: [ogImage],
    },
    twitter: {
      card: "summary_large_image",
      title: fullTitle,
      description,
      images: [ogImage.url],
    },
    ...(noIndex ? { robots: { index: false, follow: true } } : {}),
  };
}

/** Serialises JSON-LD safely for a <script type="application/ld+json">. */
export function jsonLdString(data: unknown): string {
  return JSON.stringify(data).replace(/</g, "\\u003c");
}

/**
 * schema.org HomeAndConstructionBusiness using ONLY known facts.
 * Address, phone, areas, social profiles and founding year are added only
 * when they are set in src/content/site.ts.
 */
export function businessJsonLd(config: SiteConfig = site): Record<string, unknown> {
  const sameAs = socialLinks(config.social).map((link) => link.href);
  const data: Record<string, unknown> = {
    "@context": "https://schema.org",
    "@type": "HomeAndConstructionBusiness",
    "@id": `${config.url}/#business`,
    name: config.name,
    url: config.url,
    email: config.email,
    logo: `${config.url}/brand/logo.png`,
    image: `${config.url}/brand/logo.png`,
    description: config.description,
  };
  if (config.phone) data.telephone = config.phone;
  if (config.address) {
    data.address = {
      "@type": "PostalAddress",
      streetAddress: config.address.streetAddress,
      addressLocality: config.address.locality,
      addressRegion: config.address.region,
      postalCode: config.address.postalCode,
      addressCountry: config.address.country,
    };
  }
  if (config.serviceAreas && config.serviceAreas.length > 0) {
    data.areaServed = config.serviceAreas.map((name) => ({ "@type": "City", name }));
  } else if (config.city) {
    data.areaServed = { "@type": "City", name: config.city };
  }
  if (sameAs.length > 0) data.sameAs = sameAs;
  if (config.foundingYear) data.foundingDate = String(config.foundingYear);
  return data;
}

export function breadcrumbJsonLd(baseUrl: string, crumbs: { name: string; path: string }[]) {
  return {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: crumbs.map((crumb, index) => ({
      "@type": "ListItem",
      position: index + 1,
      name: crumb.name,
      item: `${baseUrl}${crumb.path === "/" ? "" : crumb.path}`,
    })),
  };
}

export const STATIC_PAGES: { path: string; changeFrequency: "weekly" | "monthly" | "yearly"; priority: number }[] = [
  { path: "/", changeFrequency: "weekly", priority: 1 },
  { path: "/services", changeFrequency: "monthly", priority: 0.8 },
  { path: "/portfolio", changeFrequency: "weekly", priority: 0.9 },
  { path: "/about", changeFrequency: "monthly", priority: 0.6 },
  { path: "/contact", changeFrequency: "monthly", priority: 0.8 },
  { path: "/privacy", changeFrequency: "yearly", priority: 0.2 },
];

/**
 * Static pages + one entry per published portfolio item. When the API is
 * unavailable the portfolio part is simply left out — the sitemap never fails.
 */
export function buildSitemap(baseUrl: string, portfolio: PortfolioListResult): MetadataRoute.Sitemap {
  const origin = baseUrl.replace(/\/+$/, "");
  const entries: MetadataRoute.Sitemap = STATIC_PAGES.map((page) => ({
    url: `${origin}${page.path === "/" ? "" : page.path}`,
    changeFrequency: page.changeFrequency,
    priority: page.priority,
  }));

  if (portfolio.ok) {
    for (const item of portfolio.items) {
      const updated = item.updatedAt ? new Date(item.updatedAt) : null;
      entries.push({
        url: `${origin}/portfolio/${encodeURIComponent(item.slug)}`,
        changeFrequency: "monthly",
        priority: 0.7,
        ...(updated && !Number.isNaN(updated.getTime()) ? { lastModified: updated.toISOString() } : {}),
      });
    }
  }
  return entries;
}
